mapper.select:
SELECT 
FROM notification n

WHERE n.id=#{id}
  AND n.recipient_user_id=#{recipientUserId}
LIMIT 1

SELECT 
FROM notification n

WHERE n.recipient_user_id=#{recipientUserId}
AND n.is_read=0
ORDER BY n.created_at DESC,n.id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE notification
SET is_read=1,read_at=UTC_TIMESTAMP(3)
WHERE id=#{id}
  AND recipient_user_id=#{recipientUserId}
  AND is_read=0

mapper.select:
SELECT 
FROM notification n

WHERE n.recipient_user_id=#{recipientUserId}
  AND n.id > #{lastEventId}
ORDER BY n.id
LIMIT #{limit}
